import { Component, OnInit } from '@angular/core';
import {FormService} from '../service/form.service';
import {AppConstants} from '../constants/app.constants';
import {FormConfig} from '../service/form-config';
import {FormBuilder, FormControl, FormGroup, Validators} from '@angular/forms';
import {AuthService} from '../auth/auth.service';
import {Router} from '@angular/router';
import {NumberValidator} from '../validators/NumberValidator';
import {UserData} from '../auth/model/userData';

declare var $: any;

@Component({
  selector: 'app-employee',
  templateUrl: './employee.component.html',
  styleUrls: ['./employee.component.scss']
})
export class EmployeeComponent implements OnInit {

  userData = new Map( [
    ['volledigenaam', ''],
    ['geboortedatum', ''],
    ['woonplaats', '']
  ]);

  title = AppConstants.TITLE_PREFIX + 'Medewerker';
  forms: FormConfig[] = [];
  employeeForm!: FormGroup;
  submitted = false;

  noUserData = false;
  showUserData = false;
  stage = '';
  formName = '';
  constructor(
      private formService: FormService,
      private authService: AuthService,
      private formBuilder: FormBuilder,
      private router: Router
  ) { }

  ngOnInit(): void {
    this.employeeForm = this.formBuilder.group({
      identification: ['', [Validators.required, NumberValidator.isNumbers]],
      form: ['', [Validators.required]]
    });
    this.showSpinner();
    this.formService.findFormConfigEmployee().subscribe((result: FormConfig[]) => {
      this.hideSpinner();
      this.forms = result;
    });
  }

  retry(): void {
    this.submitted = false;
    this.employeeForm.controls.identification.enable();
    this.employeeForm.controls.form.enable();
    this.userData.forEach((value, key, map) => map.set(key, ''));
    this.noUserData = false;
    this.showUserData = false;
  }

  redirectToForm(): void {
    const url = '/form/' + this.stage + '/' + this.formName;
    this.router.navigateByUrl(url);
  }

  showSpinner(): void {
    $('#overlay').fadeIn();
  }

  hideSpinner(): void {
    $('#overlay').fadeOut();
  }

  onSubmit(): void {
    this.submitted = true;

    // is form valid
    if (!this.employeeForm.valid) {
      return;
    }

    // disable the input/select fields
    this.employeeForm.controls.identification.disable();
    this.employeeForm.controls.form.disable();

    // get the formname and identification
    const identification = this.employeeForm.value.identification;
    const formConfig = this.employeeForm.value.form; // this.forms.find(cfg => cfg.formName === this.employeeForm.value.form);

    // put formConfig in localStorage
    localStorage.setItem(AppConstants.FORM_CONFIG, JSON.stringify(formConfig));
    this.stage = formConfig.stage;
    this.formName = formConfig.formName;
    // @ts-ignore
    // get userdata from identification
    this.showSpinner();
    this.authService.getUserProfileAsEmployee(formConfig.formName, identification).subscribe(profile => {
      this.hideSpinner();
      if (profile) {
        if (Object.entries(profile.userData).length > 0) {
          const profileData = new Map(Object.entries(profile.userData));
          for (const key of profileData.keys()) {
            if (this.userData.has(key)){
              this.userData.set(key, profileData.get(key) as string);
            }
          }
          this.showUserData = true;
        }else{
          this.noUserData = true;
        }
        this.authService.setUserProfileSubject(profile);
        this.authService.setIsAuthenticated(true);
      }
    });
  }
}
