import { HttpClient, HttpClientModule, HttpClientXsrfModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { APP_INITIALIZER, CUSTOM_ELEMENTS_SCHEMA, NgModule } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { BrowserModule, Title } from '@angular/platform-browser';
import { JwtModule } from '@auth0/angular-jwt';
import { FormioAppConfig, FormioModule } from '@formio/angular';
import { TranslateLoader, TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranslateHttpLoader } from '@ngx-translate/http-loader';
import { CookieModule } from 'ngx-cookie';
import { TranslateCacheModule, TranslateCacheService, TranslateCacheSettings } from 'ngx-translate-cache';
import { AppConfig } from '../config';
import { getConfig } from './app-config';
import { AppRoutingModule } from './app-routing.module';
import { AppComponent } from './app.component';
import { appInitializer } from './app.initializer';
import { AuthService } from './auth/auth.service';
import { LoginComponent } from './auth/login/login.component';
import { LoginfailedComponent } from './auth/loginfailed/loginfailed.component';
import { LogoutComponent } from './auth/logout/logout.component';
import { AppConstants } from './constants/app.constants';
import { TrapFocusDirective } from './directives/trap-focus.directive';
import { EmployeeComponent } from './employee/employee.component';
import { ErrorComponent } from './error/error.component';
import { PaymentfailedComponent } from './error/paymentfailed/paymentfailed.component';
import { UniquesubmissionComponent } from './error/uniquesubmission/uniquesubmission.component';
import { FooterComponent } from './footer/footer.component';
import { FormComponent } from './form/form.component';
import { HeaderComponent } from './header/header.component';
import { HomeComponent } from './home/home.component';
import { CustomInterceptor } from './interceptor/custom.http.interceptor';
import { NotfoundComponent } from './notfound/notfound.component';
import { PaymentComponent } from './payment/payment.component';
import { PaymentSuccessComponent } from './payment/paymentsuccess.component';
import { StartPaymentComponent } from './payment/start-payment/start-payment.component';
import { PaymentsuccessfulComponent } from './paymentsuccessful/paymentsuccessful.component';
import { StageComponent } from './stage/stage.component';
import { ThanksComponent } from './thanks/thanks.component';
import { UnauthorizedComponent } from './unauthorized/unauthorized.component';
import { UnauthorizedLoginMethodComponent } from './unauthorized-login-method/unauthorized-login-method.component';

export function createTranslateLoader(http: HttpClient) {
  return new TranslateHttpLoader(http, './assets/i18n/', '.json');
}

export function TranslateCacheFactory(translateService: TranslateService, translateCacheSettings: TranslateCacheSettings) {
  return new TranslateCacheService(translateService, translateCacheSettings);
}

export function tokenGetter() {
  return localStorage.getItem(AppConstants.COOKIE_ACCESS_TOKEN);
}

@NgModule({
    declarations: [
        AppComponent,
        FormComponent,
        HeaderComponent,
        ThanksComponent,
        HomeComponent,
        LoginfailedComponent,
        StageComponent,
        UnauthorizedComponent,
        FooterComponent,
        LoginComponent,
        LogoutComponent,
        ErrorComponent,
        NotfoundComponent,
        PaymentfailedComponent,
        PaymentComponent,
        PaymentSuccessComponent,
        UniquesubmissionComponent,
        PaymentsuccessfulComponent,
        StartPaymentComponent,
        EmployeeComponent,
        TrapFocusDirective,
        UnauthorizedLoginMethodComponent,
    ],
    imports: [
        BrowserModule,
        AppRoutingModule,
        HttpClientXsrfModule,
        FormioModule,
        JwtModule.forRoot({
            config: {
                tokenGetter,
                allowedDomains: getConfig().allowedDomains,
                disallowedRoutes: getConfig().disallowedRoutes,
            }
        }),
        HttpClientModule,
        CookieModule.forRoot(),
        TranslateModule.forRoot({
            loader: {
                provide: TranslateLoader,
                useFactory: (createTranslateLoader),
                deps: [HttpClient]
            }
        }),
        TranslateCacheModule.forRoot({
            cacheService: {
                provide: TranslateCacheService,
                useFactory: TranslateCacheFactory,
                deps: [TranslateService, TranslateCacheSettings]
            }
        }),
        ReactiveFormsModule
    ],
  providers: [
      {
          provide: FormioAppConfig, useValue: AppConfig
      },
      {
          provide: APP_INITIALIZER, useFactory: appInitializer, multi: true, deps: [AuthService]
      },
      {
          provide: HTTP_INTERCEPTORS,
          useClass: CustomInterceptor ,
          multi: true
      },
      Title
  ],
    schemas: [
        CUSTOM_ELEMENTS_SCHEMA
    ],
  bootstrap: [AppComponent]
})
export class AppModule { }
